/**
 * Firestore trigger — runs whenever a message is created in a service chat
 * (`servicios/{serviceId}/mensajes/{messageId}`).
 *
 * If the message text matches any of the contact-info / off-platform bypass
 * patterns, the write is redacted in place: the offending body is replaced
 * with a system notice explaining the block. The original text is stored on a
 * private `admin_flags` document for moderation review.
 *
 * System messages (`tipo === 'sistema'`) and image messages are exempt — they
 * are generated by our own code paths, not by users.
 */

import { onDocumentCreated } from 'firebase-functions/v2/firestore';
import { db, admin } from './lib/admin';
import { scan } from './lib/contact-info-filter';
import { sendPushToUser } from './lib/push';

export const onChatMessageCreated = onDocumentCreated(
  {
    document: 'servicios/{serviceId}/mensajes/{messageId}',
    region: 'us-central1',
  },
  async (event) => {
    const snap = event.data;
    if (!snap) return;
    const data = snap.data();

    const tipo = (data.tipo as string | undefined) ?? 'texto';
    const serviceId = event.params.serviceId as string;
    const messageId = event.params.messageId as string;

    // Load the service up front. It is needed twice: to name both parties on a
    // moderation flag, and to address the push fan-out. Reading it before the
    // violation branch costs one extra read on a blocked message and saves the
    // admin screen from having to resolve participants itself.
    const serviceSnap = await db.collection('servicios').doc(serviceId).get();
    if (!serviceSnap.exists) return;
    const service = serviceSnap.data()!;
    const clienteId = service.clienteId as string | undefined;
    const tecnicoId = service.tecnicoId as string | undefined;

    // System messages skip the filter (they come from our own server) but we
    // still fan out lifecycle-event pushes below.
    if (tipo !== 'sistema') {
      const text = (data.mensaje as string | undefined) ?? '';
      const violation = tipo === 'imagen' ? null : scan(text);

      if (violation) {
        // Redact the message in place — same doc id, so client streams see
        // the block immediately without needing an extra listener.
        await snap.ref.set(
          {
            mensaje: `⚠️ Mensaje bloqueado: ${violation.message}`,
            tipo: 'sistema',
            metadata: {
              event: 'blocked_by_filter',
              reason: violation.reason,
              originalUserId: data.userId ?? null,
            },
          },
          { merge: true },
        );
        await db.collection('admin_flags').add({
          type: 'chat_contact_info_leak_attempt',
          // `servicioId` is the name used across the rest of the codebase;
          // this flag used to write `serviceId` and nothing else did.
          servicioId: serviceId,
          messageId,
          // Both participants, so the moderation screen can show who was
          // talking to whom without a second lookup per row.
          clienteId: clienteId ?? null,
          tecnicoId: tecnicoId ?? null,
          offenderUid: data.userId ?? null,
          offenderName: data.nombreUsuario ?? null,
          originalText: text,
          reason: violation.reason,
          // Review state, driven from the admin panel. No automatic sanction
          // is applied — the flag only records what happened.
          estado: 'pendiente',
          createdAt: admin.firestore.FieldValue.serverTimestamp(),
        });
        // Do NOT push a notification for a blocked message.
        return;
      }
    }

    // ---- Push notification fan-out ----
    // Push to everyone EXCEPT the sender (user messages → other party only;
    // system events → both parties since neither of them is the "sender").
    const senderUid = data.userId as string | undefined;

    const recipients = [clienteId, tecnicoId].filter(
      (u): u is string => !!u && u !== senderUid,
    );
    if (recipients.length === 0) return;

    const title = tipo === 'sistema'
      ? 'ServiTec'
      : `Nuevo mensaje · ${data.nombreUsuario ?? 'ServiTec'}`;
    const bodyPreview = tipo === 'imagen'
      ? '📷 Foto'
      : (data.mensaje as string | undefined)?.slice(0, 120) ?? '';

    await Promise.all(
      recipients.map((uid) =>
        sendPushToUser(uid, {
          title,
          body: bodyPreview,
          data: {
            type: 'chat_message',
            serviceId,
            messageId,
          },
        }),
      ),
    );
  },
);
